import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testPositiveNumber() {
        Assert.assertEquals(true, isPositive(5))
    }

    @Test
    fun testNegativeNumber() {
        Assert.assertEquals(false, isPositive(-3))
    }

    @Test
    fun testZero() {
        Assert.assertEquals(false, isPositive(0))
    }

    @Test
    fun testLargePositive() {
        Assert.assertEquals(true, isPositive(4215))
    }
}
